{
  "name": "opencode-google-grounding",
  "version": "0.2.0",
  "description": "OpenCode plugin that adds a Google Search grounding tool for Gemini/Vertex-compatible providers.",
  "type": "module",
  "main": "index.js",
  "exports": {
    ".": "./index.js"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/janaki-sasidhar/opencode-google-grounding.git"
  },
  "bugs": {
    "url": "https://github.com/janaki-sasidhar/opencode-google-grounding/issues"
  },
  "homepage": "https://github.com/janaki-sasidhar/opencode-google-grounding#readme",
  "files": [
    "index.js",
    "src/",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "gemini",
    "google-search",
    "grounding",
    "vertex-ai"
  ],
  "license": "MIT",
  "dependencies": {
    "@opencode-ai/plugin": "^1.14.20"
  },
  "engines": {
    "node": ">=20"
  },
  "scripts": {
    "test": "node --test",
    "coverage": "c8 --check-coverage --lines 96 --functions 96 --statements 96 --branches 90 node --test",
    "prepublishOnly": "npm run coverage"
  },
  "devDependencies": {
    "c8": "^11.0.0"
  }
}
